<script setup lang="ts">
import AppIcon from '../../../../../shared/components/layout/AppIcon.vue'
import type { BillingCycle, InvoiceStatus, ProjectInvoice } from '../../types/invoice'

const props = defineProps<{ invoices: ProjectInvoice[]; loading: boolean }>()
const emit = defineEmits<{ edit: [invoice: ProjectInvoice]; issue: [invoice: ProjectInvoice]; cancel: [invoice: ProjectInvoice]; replace: [invoice: ProjectInvoice]; print: [invoice: ProjectInvoice]; download: [invoice: ProjectInvoice] }>()
const money = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 })
const date = new Intl.DateTimeFormat('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
const month = new Intl.DateTimeFormat('id-ID', { month: 'long', year: 'numeric' })
function periodLabel(period: string) { return month.format(new Date(`${period}-01T00:00:00`)) }
function billingLabel(cycle: BillingCycle, period: string | null) { return cycle === 'one_time' ? 'Sekali' : period ? periodLabel(period) : 'Bulanan' }
const labels: Record<InvoiceStatus, string> = { draft: 'Draft', issued: 'Terbit', cancelled: 'Dibatalkan' }
</script>

<template>
  <div class="invoice-list">
    <div v-if="props.loading" class="list-state">Memuat invoice...</div>
    <div v-else-if="!props.invoices.length" class="list-state empty"><span><AppIcon name="invoice" :size="22" /></span><strong>Belum ada invoice</strong><small>Invoice project yang dibuat akan tampil di sini.</small></div>
    <div v-else class="table-wrap"><table><thead><tr><th>Kode invoice</th><th>Periode tagihan</th><th>Project / pelanggan</th><th>Total tagihan</th><th>Tanggal</th><th>Status</th><th><span class="sr-only">Aksi</span></th></tr></thead><tbody><tr v-for="invoice in props.invoices" :key="invoice.id"><td><span class="invoice-code">{{ invoice.code }}</span><small v-if="invoice.supersedes" class="replacement-note">Pengganti {{ invoice.supersedes.code }}</small></td><td>{{ billingLabel(invoice.billing_cycle, invoice.billing_period) }}</td><td><span class="project-cell"><strong>{{ invoice.project.name }}</strong><small>{{ invoice.project.code }} · {{ invoice.project.customer.name }}</small></span></td><td class="amount">{{ money.format(Number(invoice.amount)) }}</td><td><span class="date-cell"><strong>{{ date.format(new Date(`${invoice.issued_at}T00:00:00`)) }}</strong><small>{{ invoice.due_at ? `Jatuh tempo ${date.format(new Date(`${invoice.due_at}T00:00:00`))}` : 'Tanpa jatuh tempo' }}</small></span></td><td><span class="status" :class="invoice.status"><i></i>{{ labels[invoice.status] }}</span></td><td><div class="actions"><button v-if="invoice.status === 'draft'" type="button" :aria-label="`Edit ${invoice.code}`" title="Edit draft" @click="emit('edit', invoice)"><AppIcon name="edit" :size="15" /></button><button v-if="invoice.status === 'draft'" type="button" class="issue" :aria-label="`Terbitkan ${invoice.code}`" title="Terbitkan" @click="emit('issue', invoice)"><AppIcon name="arrow-up-right" :size="15" /></button><button v-if="invoice.status === 'issued'" type="button" class="cancel" :aria-label="`Batalkan ${invoice.code}`" title="Batalkan invoice" @click="emit('cancel', invoice)"><AppIcon name="x" :size="15" /></button><button v-if="invoice.status === 'issued' || invoice.status === 'cancelled'" type="button" :aria-label="`Cetak ${invoice.code}`" title="Cetak" @click="emit('print', invoice)"><AppIcon name="printer" :size="15" /></button><button v-if="invoice.status === 'issued' || invoice.status === 'cancelled'" type="button" :aria-label="`Download PDF ${invoice.code}`" title="Download PDF" @click="emit('download', invoice)"><AppIcon name="download" :size="15" /></button><button v-if="invoice.status === 'cancelled' && !invoice.replacement" type="button" class="issue" :aria-label="`Buat pengganti ${invoice.code}`" title="Buat invoice pengganti" @click="emit('replace', invoice)"><AppIcon name="plus" :size="15" /></button></div></td></tr></tbody></table></div>
    <div v-if="props.invoices.length && !props.loading" class="invoice-cards"><article v-for="invoice in props.invoices" :key="invoice.id" class="invoice-card"><div class="card-top"><div class="identity-copy"><strong>{{ invoice.code }}</strong><small>{{ billingLabel(invoice.billing_cycle, invoice.billing_period) }}</small></div><span class="status" :class="invoice.status"><i></i>{{ labels[invoice.status] }}</span></div><div class="card-project"><strong>{{ invoice.project.name }}</strong><small>{{ invoice.project.code }} · {{ invoice.project.customer.name }}</small></div><div class="card-details"><span><small>Tanggal</small><strong>{{ date.format(new Date(`${invoice.issued_at}T00:00:00`)) }}</strong></span><span><small>Jatuh tempo</small><strong>{{ invoice.due_at ? date.format(new Date(`${invoice.due_at}T00:00:00`)) : 'Tanpa jatuh tempo' }}</strong></span></div><div class="card-total"><span>Total tagihan</span><strong>{{ money.format(Number(invoice.amount)) }}</strong></div><small v-if="invoice.supersedes" class="replacement-note">Pengganti {{ invoice.supersedes.code }}</small><div class="card-actions"><button v-if="invoice.status === 'draft'" type="button" @click="emit('edit', invoice)"><AppIcon name="edit" :size="14" /> Edit</button><button v-if="invoice.status === 'draft'" type="button" class="issue" @click="emit('issue', invoice)"><AppIcon name="arrow-up-right" :size="14" /> Terbitkan</button><button v-if="invoice.status === 'issued'" type="button" class="cancel" @click="emit('cancel', invoice)"><AppIcon name="x" :size="14" /> Batalkan</button><button v-if="invoice.status === 'issued' || invoice.status === 'cancelled'" type="button" @click="emit('print', invoice)"><AppIcon name="printer" :size="14" /> Cetak</button><button v-if="invoice.status === 'issued' || invoice.status === 'cancelled'" type="button" @click="emit('download', invoice)"><AppIcon name="download" :size="14" /> PDF</button><button v-if="invoice.status === 'cancelled' && !invoice.replacement" type="button" class="issue" @click="emit('replace', invoice)"><AppIcon name="plus" :size="14" /> Pengganti</button></div></article></div>
  </div>
</template>

